```python
pctr = traverse_obj(player_responses, (..., 'captions', 'playerCaptionsTracklistRenderer'), expected_type=dict)
if pctr:
    def get_lang_code(track):
        return (remove_start(track.get('vssId') or '', '.').replace('.', '-')
                or track.get('languageCode'))

    # Converted into dicts to remove duplicates
    captions = {
        get_lang_code(sub): sub
        for sub in traverse_obj(pctr, (..., 'captionTracks', ...))}
    translation_languages = {
        lang.get('languageCode'): self._get_text(lang.get('languageName'), max_runs=1)
        for lang in traverse_obj(pctr, (..., 'translationLanguages', ...))}

    def process_language(container, base_url, lang_code, sub_name, query):
        lang_subs = container.setdefault(lang_code, [])
        for fmt in self._SUBTITLE_FORMATS:
            query.update({
                'fmt': fmt,
            })
            lang_subs.append({
                'ext': fmt,
                'url': urljoin('https://www.youtube.com', update_url_query(base_url, query)),
                'name': sub_name,
            })

    # NB: Constructing the full subtitle dictionary is slow
    get_translated_subs = 'translated_subs' not in self._configuration_arg('skip') and (
        self.get_param('writeautomaticsub', False) or self.get_param('listsubtitles'))
    for lang_code, caption_track in captions.items():
        base_url = caption_track.get('baseUrl')
        orig_lang = parse_qs(base_url).get('lang', [None])[-1]
        if not base_url:
            continue
        lang_name = self._get_text(caption_track, 'name', max_runs=1)
        if caption_track.get('kind') != 'asr':
            if not lang_code:
                continue
            process_language(
                subtitles, base_url, lang_code, lang_name, {})
            if not caption_track.get('isTranslatable'):
                continue
        for trans_code, trans_name in translation_languages.items():
            if not trans_code:
                continue
            orig_trans_code = trans_code
            if caption_track.get('kind') != 'asr' and trans_code != 'und':
                if not get_translated_subs:
                    continue
                trans_code += f'-{lang_code}'
                trans_name += format_field(lang_name, None, ' from %s')
            if lang_code == f'a-{orig_trans_code}':
                # Set audio language based on original subtitles
                for f in formats:
                    if f.get('acodec') != 'none' and not f.get('language'):
                        f['language'] = orig_trans_code
                # Add an "-orig" label to the original language so that it can be distinguished.
                process_language(
                    automatic_captions, base_url, f'{trans_code}-orig', f'{trans_name} (Original)', {})
            # Setting tlang=lang returns damaged subtitles.
            process_language(automatic_captions, base_url, trans_code, trans_name,
                             {} if orig_lang == orig_trans_code else {'tlang': trans_code})

info['automatic_captions'] = automatic_captions
info['subtitles'] = subtitles
```

### Key Logic:
- The `automatic_captions` are extracted from `player_responses` and stored in `automatic_captions`.
- The `get_translated_subs` condition determines whether translated subtitles are included:
  ```python
  get_translated_subs = 'translated_subs' not in self._configuration_arg('skip') and (
      self.get_param('writeautomaticsub', False) or self.get_param('listsubtitles'))
  ```
